/**
 * 将验证 JSON 渲染为 Markdown 报告
 * JSON 解析失败时返回 null
 */
export function renderVerificationReport(jsonContent: string): string | null {
  const parsed = parseVerificationReportJson(jsonContent);
  if (!parsed.valid || !parsed.report) return null;
  const data: VerificationReportContract = parsed.report;

  const displayEvidence = (claim: { evidence?: string; evidence_refs?: string[] }): string =>
    claim.evidence ?? claim.evidence_refs?.join(', ') ?? '';
  const statusIcon = (status: string): string =>
    status === 'pass' ? '✅' : ['skip', 'skipped', 'not_applicable'].includes(status) ? '➖' : '❌';

  // 统计汇总
  const allChecks = [
    ...data.verification_commands.map(c => c.status),
    ...data.acceptance_criteria.map(c => c.status),
    ...data.e2e_tests.map(c => c.status),
  ];
  const totalChecks = allChecks.length;
  const passedChecks = allChecks.filter(s =>
    ['pass', 'skip', 'skipped', 'not_applicable'].includes(s)
  ).length;
  const failedChecks = allChecks.filter(s => s === 'fail').length;

  const lines: string[] = [];

  lines.push('# 验证报告');
  lines.push('');
  lines.push('## 结果汇总');
  lines.push('');
  lines.push('| 指标 | 数值 |');
  lines.push('|------|------|');
  lines.push(`| 总检查数 | ${totalChecks} |`);
  lines.push(`| 通过 | ${passedChecks} |`);
  lines.push(`| 失败 | ${failedChecks} |`);
  lines.push(`| 结论 | ${data.conclusion} |`);
  lines.push('');

  // 章节 1: 验证命令
  lines.push('## 验证命令');
  lines.push('');
  if (data.verification_commands.length > 0) {
    lines.push('| 命令 | 状态 | 输出摘要 |');
    lines.push('|------|------|----------|');
    for (const cmd of data.verification_commands) {
      const icon = statusIcon(cmd.status);
      lines.push(`| \`${cmd.command}\` | ${icon} ${cmd.status} | ${cmd.output_summary} |`);
    }
  } else {
    lines.push('无验证命令。');
  }
  lines.push('');

  // 章节 2: 验收标准
  lines.push('## 验收标准');
  lines.push('');
  if (data.acceptance_criteria.length > 0) {
    lines.push('| 需求 | 名称 | 状态 | 证据 |');
    lines.push('|------|------|------|------|');
    for (const ac of data.acceptance_criteria) {
      const icon = statusIcon(ac.status);
      lines.push(`| ${ac.req_id} | ${ac.name} | ${icon} ${ac.status} | ${displayEvidence(ac)} |`);
    }
  } else {
    lines.push('无验收标准检查。');
  }
  lines.push('');

  // 章节 3: 端到端测试
  lines.push('## 端到端测试');
  lines.push('');
  if (data.e2e_tests.length > 0) {
    lines.push('| 测试名称 | 状态 | 证据 |');
    lines.push('|----------|------|------|');
    for (const e2e of data.e2e_tests) {
      const icon = statusIcon(e2e.status);
      lines.push(`| ${e2e.name} | ${icon} ${e2e.status} | ${displayEvidence(e2e)} |`);
    }
  } else {
    lines.push('无端到端测试。');
  }
  lines.push('');

  // 章节 4: 副作用
  lines.push('## 副作用');
  lines.push('');
  lines.push(data.side_effects || '无副作用。');
  lines.push('');

  // 章节 5: 结论
  lines.push('## 结论');
  lines.push('');
  lines.push(`**结论：${data.conclusion}**`);
  lines.push('');
  lines.push(data.summary || '');
  lines.push('');

  // Preserve the complete structured verifier output as the executable
  // producer/consumer contract. semantic-closure-builder can read the nested
  // semantic_closure object from this fenced JSON for backward compatibility,
  // while the preferred path passes it directly to sf_semantic_closure_run.
  lines.push('## Machine-readable Verification Contract');
  lines.push('');
  lines.push('```json');
  lines.push(JSON.stringify(data, null, 2));
  lines.push('```');
  lines.push('');

  return lines.join('\n');
}

