function rejectProfessionalArtifactOwnership(fileType: string, context: any): any | null {
  const requiredAgent = PROFESSIONAL_ARTIFACT_OWNERS.get(String(fileType ?? ''));
  if (!requiredAgent) return null;

  const callerAgent = normalizeAgentName(context?.agent) || 'unknown';
  if (callerAgent === requiredAgent) return null;
  return {
    success: false,
    error: 'ARTIFACT_OWNER_MISMATCH',
    hard_stop: false,
    policy_violation: true,
    retry_allowed: true,
    file_type: fileType,
    caller_agent: callerAgent,
    required_agent: requiredAgent,
    message:
      `Artifact type "${fileType}" is owned by ${requiredAgent}. ` +
      'sf-orchestrator must re-dispatch the owning professional agent instead of writing the artifact itself.',
  };
}
const EXECUTOR_FORBIDDEN_ARTIFACT_TYPES = new Set([
  'work_item',
  'work_item.json',
  'intake',
  'change_classification',
  'impact_analysis',
  'trigger_result',
  'investigation_plan',
  'findings_report',
  'requirements',
  'design',
  'requirements_delta',
  'design_delta',
  'tasks',
  'trace_delta',
  'candidate_manifest',
  'merge_report',
  'verification_report',
  'evidence_manifest',
  'verification_evidence',
  'candidate_requirements',
  'candidate_architecture',
  'candidate_data_model',
  'candidate_design',
  'candidate_module_definition',
  'candidate_module_contract',
  'candidate_tasks',
  'candidate_trace_delta',
  'candidate_module_trace',
  'project_prod_environment',
  'project_rules',
]);
function rejectExecutorGovernanceArtifact(fileType: string, context: any): any | null {
  if (!isExecutorLike(context)) return null;
  if (!EXECUTOR_FORBIDDEN_ARTIFACT_TYPES.has(String(fileType ?? ''))) return null;
  return {
    success: false,
    error: 'EXECUTOR_CANNOT_WRITE_GOVERNANCE_ARTIFACTS',
    hard_stop: false,
    policy_violation: true,
    retry_allowed: true,
    file_type: fileType,
    message:
      'sf-executor must return a task report to the orchestrator. Governance artifacts under .specforge/work-items must be written by orchestrator/verifier/planner through controlled tools.',
  };
}
registerHandler('sf_artifact_write', async (args, context, deps) => {
  const baseDir = (context?.directory as string) || (context?.worktree as string) || process.cwd();
  const workItemId = args['work_item_id'] as string;
  let fileType = args['file_type'] as string;
  let content = stringifyArtifactContent(args['content'], args['agent_content']);

  const initialControlOwnerRejection = rejectControlToolOwnedArtifact(fileType);
  if (initialControlOwnerRejection) return initialControlOwnerRejection;
  const initialExecutorRejection = rejectExecutorGovernanceArtifact(fileType, context);
  if (initialExecutorRejection) return initialExecutorRejection;
  const initialOwnershipRejection = rejectProfessionalArtifactOwnership(fileType, context);
  if (initialOwnershipRejection) return initialOwnershipRejection;

  const idError = validateWorkItemId(workItemId);
  if (idError) return { success: false, error: idError, hard_stop: false, retry_allowed: true };
  const guardResult = guardHardStop(baseDir, workItemId, 'sf_artifact_write');
  if (!guardResult.allowed) {
    return {
      success: false,
      error: guardResult.error,
      hard_stop: true,
      hard_stop_record: guardResult.hard_stop_record,
    };
  }

  const metadataWorkItemDir = workItemRoot(baseDir, workItemId);
  try {
    await readWorkItemMetadata(metadataWorkItemDir, workItemId);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : String(error),
      hard_stop: true,
      retry_allowed: false,
    };
  }

  const inferred = inferCanonicalFileType(args);
  if (inferred) fileType = inferred;

  const inferredControlOwnerRejection = rejectControlToolOwnedArtifact(fileType);
  if (inferredControlOwnerRejection) return inferredControlOwnerRejection;
  const inferredExecutorRejection = rejectExecutorGovernanceArtifact(fileType, context);
  if (inferredExecutorRejection) return inferredExecutorRejection;
  const inferredOwnershipRejection = rejectProfessionalArtifactOwnership(fileType, context);
  if (inferredOwnershipRejection) return inferredOwnershipRejection;
  if (fileType === 'verification_evidence') {
    const state = await readAuthoritativeState({ deps, projectRoot: baseDir, workItemId });
    if (!['implementation_ready', 'implementation_done', 'verification_running'].includes(
      String(state.current_state ?? ''),
    )) {
      return { success: false, error: 'VERIFICATION_EVIDENCE_STATE_FROZEN',
        current_state: state.current_state, retry_allowed: false };
    }
    const name = String(args['artifact_name'] ?? '');
    if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,100}\.(?:jsonl|txt|png|webp|jpg|jpeg)$/.test(name)) {
      return { success: false, error: 'VERIFICATION_EVIDENCE_NAME_INVALID', retry_allowed: true };
    }
    const encoding = String(args['content_encoding'] ?? 'utf8');
    if (!['utf8', 'base64'].includes(encoding) ||
        (encoding === 'base64' && (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(content) ||
          Buffer.from(content, 'base64').toString('base64') !== content))) {
      return { success: false, error: 'VERIFICATION_EVIDENCE_ENCODING_INVALID', retry_allowed: true };
    }
    const bytes = Buffer.from(content, encoding as BufferEncoding);
    if (bytes.byteLength === 0 || bytes.byteLength > 10 * 1024 * 1024) {
      return { success: false, error: 'VERIFICATION_EVIDENCE_SIZE_INVALID', retry_allowed: true };
    }
    const evidenceDir = path.join(metadataWorkItemDir, 'evidence', 'source');
    const target = path.join(evidenceDir, name);
    try {
      fs.mkdirSync(evidenceDir, { recursive: true });
      fs.writeFileSync(target, bytes, { flag: 'wx' });
    } catch (error: any) {
      if (error?.code === 'EEXIST') {
        return { success: false, error: 'VERIFICATION_EVIDENCE_ALREADY_EXISTS', retry_allowed: true };
      }
      setHardStop(baseDir, workItemId, `VERIFICATION_EVIDENCE_WRITE_FAILED: ${error?.message ?? String(error)}`, 'sf_artifact_write');
      return { success: false, error: 'VERIFICATION_EVIDENCE_WRITE_FAILED', hard_stop: true };
    }
    return { success: true, file_type: fileType,
      path: path.relative(baseDir, target).replace(/\\/g, '/'),
      size: bytes.byteLength,
      sha256: createHash('sha256').update(bytes).digest('hex'),
      recorded_at: new Date().toISOString(),
      controlled_artifact: true, immutable: true };
  }
  const projectConfigTarget = PROJECT_CONFIG_ARTIFACT_TYPES.get(fileType);
  if (projectConfigTarget) {
    const callerAgent = normalizeAgentName(context?.agent) || 'unknown';
    if (callerAgent !== 'sf-orchestrator') {
      return {
        success: false,
        error: 'PROJECT_CONFIG_OWNER_MISMATCH',
        hard_stop: false,
        retry_allowed: true,
        caller_agent: callerAgent,
        required_agent: 'sf-orchestrator',
      };
    }
    const state = await readAuthoritativeState({ deps, projectRoot: baseDir, workItemId });
    if (state.current_state !== 'intake_ready') {
      return {
        success: false,
        error: 'PROJECT_CONFIG_WRITE_STATE_INVALID',
        hard_stop: false,
        retry_allowed: false,
        current_state: state.current_state,
        required_state: 'intake_ready',
        message:
          'Project configuration may only be established during intake_ready. Recover the same Work Item to the legal intake boundary instead of bypassing Write Guard.',
      };
    }
    if (isPlaceholderProjectConfigContent(content)) {
      return {
        success: false,
        error: 'PROJECT_CONFIG_CONTENT_REQUIRED',
        hard_stop: false,
        retry_allowed: true,
      };
    }
    const targetPath = path.join(baseDir, SPEC_DIR_NAME, projectConfigTarget);
    try {
      fs.mkdirSync(path.dirname(targetPath), { recursive: true });
      fs.writeFileSync(targetPath, content, 'utf-8');
      return {
        success: true,
        path: path.relative(baseDir, targetPath).replace(/\\/g, '/'),
        size: Buffer.byteLength(content, 'utf-8'),
        file_type: fileType,
        controlled_project_config: true,
        state_authority: state.source,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      setHardStop(baseDir, workItemId, `PROJECT_CONFIG_WRITE_FAILED: ${message}`, 'sf_artifact_write');
      return { success: false, error: `PROJECT_CONFIG_WRITE_FAILED: ${message}`, hard_stop: true };
    }
  }
  if (VERIFICATION_INPUT_ARTIFACT_TYPES.has(fileType)) {
    const state = await readAuthoritativeState({
      deps,
      projectRoot: baseDir,
      workItemId,
    });
    if (
      ['verification_done', 'closed', 'rejected', 'superseded'].includes(
        String(state.current_state ?? '')
      )
    ) {
      return {
        success: false,
        error: 'VERIFICATION_INPUTS_FROZEN',
        hard_stop: false,
        retry_allowed: false,
        current_state: state.current_state,
        state_authority: state.source,
        message:
          'verification_report and evidence_manifest are frozen after verification_gate passes. ' +
          'Recover to implementation_ready before changing verification evidence, then regenerate semantic closure and rerun verification_gate.',
      };
    }
  }
  if (fileType === 'verification_report' && args['template'] !== 'verification_report') {
    return {
      success: false,
      error: 'VERIFICATION_REPORT_TEMPLATE_REQUIRED',
      hard_stop: false,
      retry_allowed: true,
      message:
        'verification_report must use template=verification_report with the structured Verification JSON contract.',
    };
  }
  if (fileType === 'verification_report' && args['template'] === 'verification_report') {
    const validation = parseVerificationReportJson(content);
    if (!validation.valid) {
      return {
        success: false,
        error: 'INVALID_VERIFICATION_REPORT_CONTRACT',
        hard_stop: false,
        retry_allowed: true,
        contract_id: VERIFICATION_REPORT_CONTRACT_ID,
        validation_errors: validation.errors,
        message:
          `verification_report failed ${VERIFICATION_REPORT_CONTRACT_ID} validation and was NOT written to disk. ` +
          'Use the sf-verifier Required Output contract exactly, then retry.',
      };
    }
    const rendered = renderVerificationReport(content);
    if (rendered === null) {
      return {
        success: false,
        error: 'INVALID_VERIFICATION_REPORT_JSON',
        hard_stop: false,
        retry_allowed: true,
        message:
          'template=verification_report requires a JSON object with conclusion and structured verification fields.',
      };
    }
    content = rendered;
  }
  let candidateModuleId: string | undefined;
  if (
    fileType === 'requirements' ||
    fileType === 'candidate_requirements' ||
    fileType === 'design' ||
    fileType === 'candidate_design' ||
    fileType === 'candidate_module_definition' ||
    fileType === 'candidate_module_contract' ||
    fileType === 'candidate_module_trace'
  ) {
    const moduleResolution = resolveDeclaredCandidateModuleId(
      content,
      baseDir,
      workItemId,
      args['module_id']
    );
    if (!moduleResolution.moduleId) {
      return {
        success: false,
        error: moduleResolution.error,
        hard_stop: false,
        retry_allowed: true,
        declared_modules: moduleResolution.declared,
      };
    }
    candidateModuleId = moduleResolution.moduleId;
    if (fileType === 'candidate_module_definition') {
      try {
        const identity = resolveSpecModuleIdentity(JSON.parse(content));
        if (!identity.valid || identity.moduleCode !== candidateModuleId) {
          return {
            success: false,
            error: `MODULE_DEFINITION_INVALID: module.json Candidate must declare canonical module_code ${candidateModuleId}. ${identity.errors.join('; ')}`,
            hard_stop: false,
            retry_allowed: true,
          };
        }
      } catch (error) {
        return {
          success: false,
          error: `MODULE_DEFINITION_INVALID: ${(error as Error).message}`,
          hard_stop: false,
          retry_allowed: true,
        };
      }
    }
  }
  const targetFilename = resolveTargetFilename(
    fileType,
    content,
    baseDir,
    workItemId,
    candidateModuleId
  );
  if (!targetFilename && String(args['file_type']) === 'work_log') {
    return writeArtifact(
      {
        work_item_id: workItemId,
        file_type: 'work_log' as any,
        content,
        run_id: args['run_id'] as string | undefined,
        template: args['template'] as any,
        agent_content: args['agent_content'] as string | undefined,
      },
      baseDir
    );
  }
  if (!targetFilename) {
    return writeArtifact(
      {
        work_item_id: workItemId,
        file_type: fileType as any,
        content,
        run_id: args['run_id'] as string | undefined,
        template: args['template'] as any,
        agent_content: args['agent_content'] as string | undefined,
      },
      baseDir
    );
  }
  if (targetFilename.replace(/\\/g, '/').endsWith('/tasks.md') || targetFilename === 'tasks.md') {
    const validation = validateTaskArtifactContract(content, { requireAllowedWriteFiles: true });
    if (!validation.valid) {
      return {
        success: false,
        error: 'INVALID_TASK_ARTIFACT_CONTRACT',
        hard_stop: false,
        retry_allowed: true,
        contract_version: validation.contract_version,
        validation_errors: validation.issues.filter(issue => issue.severity === 'error'),
        validation_warnings: validation.issues.filter(issue => issue.severity === 'warning'),
        message:
          `Artifact "${targetFilename}" failed task-document/v1 validation and was NOT written to disk. ` +
          'Use canonical IDs, refs, allowed_write_files, and typed verification_commands, then retry.',
      };
    }
  }
  if (fileType === 'design' || fileType === 'candidate_design' || fileType === 'design_delta') {
    const requirement = await resolveSystemGovernanceRequirement(workItemId, baseDir);
    if (requirement.blocking_issue) {
      return {
        success: false,
        error: 'DESIGN_SCOPE_AUTHORITY_UNAVAILABLE',
        hard_stop: false,
        retry_allowed: true,
        source_path: requirement.source_path,
        message:
          `${requirement.blocking_issue}. ` +
          'The design artifact was NOT written because Runtime cannot derive its required analysis_scope.',
      };
    }
    const requiredScope = requirement.required ? 'system_governance' : 'solution_design';
    const declaredScope = readDeclaredDesignAnalysisScope(content);
    const moduleOwnership = readModuleOwnership(baseDir);
    const explicitModuleProjection =
      requirement.required &&
      fileType !== 'design_delta' &&
      typeof args['module_id'] === 'string' &&
      Boolean(candidateModuleId) &&
      Boolean(moduleOwnership.defaultModule) &&
      candidateModuleId !== moduleOwnership.defaultModule;
    const allowedScopes = explicitModuleProjection ? ['solution_design'] : [requiredScope];
    if (!declaredScope || !allowedScopes.includes(declaredScope)) {
      return {
        success: false,
        error: 'DESIGN_SCOPE_CONTRACT_MISMATCH',
        hard_stop: false,
        retry_allowed: true,
        required_analysis_scope: requiredScope,
        allowed_analysis_scopes: allowedScopes,
        declared_analysis_scope: declaredScope,
        derivation_reasons: requirement.reasons,
        source_path: requirement.source_path,
        message:
          `Design artifact must declare one allowed analysis_scope: ${allowedScopes.join(', ')}. ` +
          'Overall governance design remains system_governance; explicit non-default module projections use solution_design. The artifact was NOT written.',
      };
    }
  }
  if (isCandidateGovernancePath(targetFilename)) {
    const state = await readAuthoritativeState({
      deps,
      projectRoot: baseDir,
      workItemId,
    });
    if (!state.current_state) {
      return {
        success: false,
        error: 'CANDIDATE_FREEZE_STATE_UNAVAILABLE',
        hard_stop: false,
        retry_allowed: true,
        message:
          'Candidate write denied because the authoritative StateManager state could not be read.',
      };
    }
    if (isCandidateFrozenState(state.current_state)) {
      return {
        success: false,
        error: 'CANDIDATE_FROZEN',
        hard_stop: false,
        retry_allowed: false,
        current_state: state.current_state,
        state_authority: state.source,
        message:
          `Candidate artifacts are frozen while WI state is ${state.current_state}. ` +
          'Invalidate the approval and recover to candidate_preparing before editing.',
      };
    }
  }
  if (['change_classification.md', 'impact_analysis.md', 'trigger_result.json'].includes(targetFilename)) {
    const state = await readAuthoritativeState({ deps, projectRoot: baseDir, workItemId });
    const mutableStates = new Set(['impact_analyzing', 'candidate_preparing', 'gates_failed']);
    if (!state.current_state || !mutableStates.has(state.current_state)) {
      return {
        success: false,
        error: 'CANDIDATE_BASIS_FROZEN',
        hard_stop: false,
        retry_allowed: false,
        current_state: state.current_state,
        state_authority: state.source,
        message:
          'Candidate basis artifacts are sealed outside impact_analyzing, candidate_preparing, or gates_failed. ' +
          'From candidate_prepared transition to blocked and recover to candidate_preparing before repair; do not invoke a known-invalid Gate merely to reach gates_failed.',
      };
    }
  }
  if (targetFilename === 'evidence_manifest.json') {
    const schemaPrecheck = await precheckEvidenceManifestSchema(
      workItemRoot(baseDir, workItemId),
      workItemId,
    );
    const schemaBlockCode = evidenceManifestSchemaBlockCode(schemaPrecheck);
    if (schemaBlockCode) {
      return {
        success: false,
        error: `EVIDENCE_MANIFEST_SCHEMA_BLOCKED: ${schemaBlockCode}`,
        hard_stop: true,
        retry_allowed: false,
      };
    }
  }
  if (isJsonArtifact(targetFilename)) {
    try {
      content = normalizeCoreJsonArtifact(targetFilename, content, workItemId, baseDir);
    } catch (error: any) {
      return {
        success: false,
        error: `ARTIFACT_NORMALIZATION_FAILED: ${error?.message ?? String(error)}`,
        hard_stop: false,
        retry_allowed: true,
      };
    }
    if (targetFilename === 'candidate_manifest.json') {
      const contentBlockCode = candidateManifestContentBlockCode(content, workItemId);
      if (contentBlockCode) {
        return {
          success: false,
          error: `CANDIDATE_MANIFEST_SCHEMA_BLOCKED: ${contentBlockCode}`,
          hard_stop: true,
          retry_allowed: false,
        };
      }
      const schemaPrecheck = await precheckCandidateManifestSchema(
        metadataWorkItemDir,
        workItemId,
      );
      const schemaBlockCode = candidateManifestSchemaBlockCode(schemaPrecheck);
      if (schemaBlockCode) {
        return {
          success: false,
          error: `CANDIDATE_MANIFEST_SCHEMA_BLOCKED: ${schemaBlockCode}`,
          hard_stop: true,
          retry_allowed: false,
        };
      }
    }
    let workflowPath: string | undefined;
    try {
      const facts = inferWorkflowFacts(baseDir, workItemId, JSON.parse(content));
      workflowPath = facts.workflowPath;
    } catch {
      // non-critical; validator can still validate with artifact content.
    }
    const validation = validateArtifactJson(targetFilename, content, workItemId, workflowPath);
    if (validation && !validation.valid) {
      return {
        success: false,
        error: 'INVALID_ARTIFACT_JSON',
        hard_stop: false,
        retry_allowed: true,
        validation_errors: validation.errors,
        message: `Artifact "${targetFilename}" failed schema validation and was NOT written to disk.\nCorrect the JSON and retry.`,
        normalized_content_preview: content.slice(0, 2000),
      };
    }
  }
  const wiDir = workItemRoot(baseDir, workItemId);
  fs.mkdirSync(wiDir, { recursive: true });
  let targetPath: string;
  if (targetFilename === 'evidence_manifest.json') {
    const evidenceDir = path.join(wiDir, 'evidence');
    fs.mkdirSync(evidenceDir, { recursive: true });
    targetPath = path.join(evidenceDir, 'evidence_manifest.json');
  } else {
    targetPath = path.join(wiDir, targetFilename);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
  }
  try {
    fs.writeFileSync(targetPath, content, 'utf-8');
    const size = Buffer.byteLength(content, 'utf-8');
    const relativePath = path.relative(baseDir, targetPath).replace(/\\/g, '/');
    return {
      success: true,
      path: relativePath,
      size,
      file_type: fileType,
      controlled_artifact: true,
      normalized: isJsonArtifact(targetFilename),
    };
  } catch (err: any) {
    setHardStop(baseDir, workItemId, `ARTIFACT_WRITE_FAILED: ${err.message}`, 'sf_artifact_write');
    return { success: false, error: `ARTIFACT_WRITE_FAILED: ${err.message}`, hard_stop: true };
  }
});
